// Worker entry in front of OpenNext. Finished HTML is kept in R2 so crawlers and readers never pay the
// Payload render, which can exceed the free plan's CPU limit (Error 1102). Old saju routes move to saju.pinda.kr.
// @ts-expect-error generated by opennextjs-cloudflare build
import next from './.open-next/worker.js'

type Env = {
  R2: R2Bucket
  CF_VERSION_METADATA: { id: string }
}

const SAJU = 'https://saju.pinda.kr'
const LEGACY =
  /^\/(s\/|og\/|og\.png$|blog(\/|$)|guide$|pay\/|app\/|icons\/|js\/|manifest\.webmanifest$|api\/(auth|chat|chats|coupon|me|pass|pay|ping|share|admin)(\/|$))/
const NEVER_CACHE = /^\/(admin|api|search|_next)(\/|$)/
const EDGE_TTL = 300
const edge = (caches as unknown as { default: Cache }).default

// An installed PWA keeps this script until the origin replaces it; a redirect would leave it registered forever.
const UNREGISTER_SW = `self.addEventListener("install",()=>self.skipWaiting());
self.addEventListener("activate",async()=>{for(const k of await caches.keys())await caches.delete(k);await self.registration.unregister();for(const c of await self.clients.matchAll())c.navigate(c.url)});
`

const isPageRead = (req: Request, url: URL) =>
  (req.method === 'GET' || req.method === 'HEAD') &&
  !NEVER_CACHE.test(url.pathname) &&
  !req.headers.has('rsc') &&
  !url.searchParams.has('_rsc') &&
  !(req.headers.get('cookie') ?? '').includes('payload-token')

const worker = {
  async fetch(req: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
    const url = new URL(req.url)
    if (url.hostname === 'www.pinda.kr' || url.protocol === 'http:') {
      return Response.redirect(`https://pinda.kr${url.pathname}${url.search}`, 301)
    }
    if (url.pathname === '/sw.js') {
      return new Response(UNREGISTER_SW, {
        headers: { 'content-type': 'text/javascript; charset=utf-8', 'cache-control': 'no-store' },
      })
    }
    // A payment notice started before the move has to reach the order, and PayApp will not follow a redirect.
    if (url.pathname === '/api/pay/feedback') {
      return fetch(`${SAJU}${url.pathname}${url.search}`, req)
    }
    // Installed apps open /?source=app; the home page is no longer theirs.
    if (LEGACY.test(url.pathname) || (url.pathname === '/' && url.searchParams.get('source') === 'app')) {
      const status = req.method === 'GET' || req.method === 'HEAD' ? 301 : 308
      return Response.redirect(`${SAJU}${url.pathname}${url.search}`, status)
    }
    if (!isPageRead(req, url)) return next.fetch(req, env, ctx)

    // Query strings (utm etc.) do not change a page, so they share one entry. A new deploy gets a new prefix.
    const edgeKey = new Request(`${url.origin}${url.pathname}`)
    const edgeHit = await edge.match(edgeKey)
    if (edgeHit) return edgeHit

    const objectKey = `html/${env.CF_VERSION_METADATA.id}${url.pathname}`
    const stored = await env.R2.get(objectKey)
    const respond = (body: BodyInit | null, type: string) => {
      const res = new Response(body, {
        headers: { 'content-type': type, 'cache-control': `public, max-age=${EDGE_TTL}` },
      })
      ctx.waitUntil(edge.put(edgeKey, res.clone()))
      return res
    }
    if (stored) return respond(stored.body, stored.httpMetadata?.contentType ?? 'text/html; charset=utf-8')

    const res: Response = await next.fetch(req, env, ctx)
    const type = res.headers.get('content-type') ?? ''
    if (res.status !== 200 || !/html|xml/.test(type)) return res
    const body = await res.text()
    ctx.waitUntil(env.R2.put(objectKey, body, { httpMetadata: { contentType: type } }))
    return respond(body, type)
  },
}

export default worker
